#!/usr/bin/env node
/* Outsider plugin hook entry — generated by src/outsider-plugin.js. */
import { handleHookInvocation } from "../src/outsider-hook.js";
import { requestController } from "../src/outsider-controller-rpc.js";
import { requestAttached } from "../src/outsider-attached-client.js";
import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { workerDigest } from "../src/outsider-worker-adapter.js";

/*
 * ── WHICH HOST IS THIS, ACTUALLY ────────────────────────────────────────────
 *
 * This read argv[2] positionally, and the two install paths disagreed about
 * what sits there. The plugin writes '… outsider-hook.mjs claude-code'; the
 * installer writes '… outsider-hook.mjs hook claude-code'. So every machine
 * installed via 'node install.mjs' — the documented path — ran with
 * agent = "hook", which matches no parser and falls through to the regex
 * heuristic. Measured on a real session, same log, both settings:
 *
 *     agent="claude-code"   1303 steps · 278 edits · 206 tests · 1245 exit codes
 *     agent="hook"           261 steps · 220 edits ·  23 tests ·   19 exit codes
 *
 * 1.5% of the exit codes. Every layer that judges a test outcome — 出厂验收,
 * stale-green, red-at-delivery, whack-a-mole — was running on that. And every
 * number ever reported for this product was measured by calling the reader
 * directly with "claude-code", i.e. from a configuration no user ever had.
 *
 * The fix is not to renumber the argument. It is to stop reading it
 * positionally: scan argv for a name we actually support, and if none is there,
 * SAY SO on stderr rather than silently degrading. A supervisor that cannot be
 * seen failing is worse than no supervisor — fourth time in this repo.
 */
const KNOWN_AGENTS = ["claude-code", "codex", "codebuddy", "trae", "claude-desktop"];
const agent = process.argv.slice(2).find((a) => KNOWN_AGENTS.includes(a)) ?? (() => {
  process.stderr.write("outsider: 命令行里没有认得出的 agent 名字（"
    + KNOWN_AGENTS.join(" / ") + "）—— 按 claude-code 解析。"
    + "如果你装的是别的宿主，重跑一次 node install.mjs。\n");
  return "claude-code";
})();
const strict = process.argv.includes("--strict") || process.env.OUTSIDER_STRICT === "1";

/*
 * WRITE THEN LET GO — never process.exit() straight after a write.
 *
 * stdout to a pipe is ASYNCHRONOUS in Node. process.exit() tears the process
 * down without draining the buffer, so under load the host receives half a JSON
 * object. It parses as malformed, the host treats a malformed hook reply as a
 * non-blocking error, and the supervisor is silently not running — the failure
 * mode this file's own header calls out as the one we must never have. Hand the
 * write a callback and let the event loop end the process on its own.
 */
const finish = (payload, note, exitCode = 0) => {
  if (note) process.stderr.write("outsider: " + note + "\n");
  process.exitCode = exitCode;
  process.stdout.write(payload, () => { /* flushed; the loop ends by itself */ });
};

/*
 * HARD DEADLINE, ARMED BEFORE ANY SLOW WORK.
 *
 * Both hosts kill a hook that overruns (Codex is configured at 30s). A killed
 * hook produces no output and no explanation, so a supervisor that gets slower
 * than its own budget disappears without telling anyone. The budget is spent
 * here, not by the host: if the decision is not back in time we ship a defer and
 * SAY that this call went unsupervised. unref() so a fast call is never delayed
 * by a pending timer.
 */
const CONTROLLER_SOCKET = process.env.OUTSIDER_CONTROLLER_SOCKET || null;
const CONTROLLER_TOKEN = process.env.OUTSIDER_CONTROLLER_TOKEN || null;
const CODEX_ATTACHED_CONTROL = agent === "codex" && process.argv.includes("--attached-control");
const CODEX_RUNTIME = CODEX_ATTACHED_CONTROL ? {
  hookMetadataFile: process.env.OUTSIDER_CODEX_HOOK_METADATA_FILE ?? null,
  entrypointHash: workerDigest(readFileSync(fileURLToPath(import.meta.url))),
  argvHash: workerDigest(process.argv.slice(2)),
} : null;
const ATTACHED_MODE = !CONTROLLER_SOCKET
  && (agent === "claude-code" || agent === "claude-desktop" || CODEX_ATTACHED_CONTROL);
/* In normal installed use the host owns the Claude process, while Outsider's
   lazy sidecar owns the synchronous hook boundary.  That path is every bit as
   controlled as outsider run and therefore gets the same bounded semantic
   budget; a five-second observer timeout would silently turn it back into a
   detector. */
const BUDGET_MS = Number(process.env.OUTSIDER_BUDGET_MS
  ?? (CONTROLLER_SOCKET || ATTACHED_MODE ? 890000 : 5000));
let done = false;
let input = {};
const deadline = setTimeout(() => {
  if (done) return;
  done = true;
  const event = input.hook_event_name ?? input.hookEventName;
  const lifecycleExit2 = event === "TaskCompleted" || event === "TeammateIdle"
    || event === "TaskCreated";
  const failed = event === "Stop" || event === "SubagentStop"
    ? { decision: "block", reason: "outsider controller 超时；本次运行没有被证明完成。请继续等待。" }
    : event === "PreToolUse"
      ? { hookSpecificOutput: { hookEventName: "PreToolUse", permissionDecision: "deny",
        permissionDecisionReason: "outsider controller 超时；本次工具调用没有被监督，已暂停。" } }
      : {};
  finish(lifecycleExit2 ? "" : JSON.stringify(ATTACHED_MODE || CONTROLLER_SOCKET ? failed : {}),
    "超过 " + BUDGET_MS + "ms 预算，本次动作未被监督", lifecycleExit2 ? 2 : 0);
}, BUDGET_MS);
deadline.unref();

let raw = "";
try { const { readFileSync } = await import("node:fs"); raw = readFileSync(0, "utf8"); } catch { raw = ""; }

try { input = JSON.parse(raw || "{}"); } catch {
  done = true; clearTimeout(deadline);
  finish("{}", "钩子输入不是合法 JSON —— 本次动作未被监督");
}

if (!done) {
  try {
    const { decision, output } = CONTROLLER_SOCKET
      ? await requestController({
        socketPath: CONTROLLER_SOCKET,
        token: CONTROLLER_TOKEN,
        payload: { agent, input, strict },
        timeoutMs: Math.max(1000, BUDGET_MS - 1000),
      })
      : ATTACHED_MODE
        ? await requestAttached({ payload: { agent, input, strict,
          ...(CODEX_RUNTIME ? { codexRuntime: CODEX_RUNTIME } : {}) },
          timeoutMs: Math.max(1000, BUDGET_MS - 1000) })
        : handleHookInvocation({ agent, input, strict });
    if (!done) {
      done = true; clearTimeout(deadline);
      const exitCode = Number(output?._outsiderExitCode ?? 0);
      const lifecycleReason = output?._outsiderStderr ?? null;
      if (decision?.corrective && decision.verdict !== "allow") {
        process.stderr.write("outsider[" + decision.verdict + "]: " + decision.corrective + "\n");
      }
      const clean = Object.fromEntries(
        Object.entries(output ?? {}).filter(([k]) => !k.startsWith("_outsider")));
      finish(exitCode === 2 ? "" : JSON.stringify(clean), lifecycleReason, exitCode);
    }
  } catch (err) {
    /* FAIL VISIBLE, NOT FAIL SILENT: the host would run the tool regardless, so
       the one thing we owe the operator is to say that we did not check it. */
    if (!done) {
      done = true; clearTimeout(deadline);
      const event = input.hook_event_name ?? input.hookEventName;
      const lifecycleExit2 = event === "TaskCompleted" || event === "TeammateIdle"
        || event === "TaskCreated";
      const failed = event === "Stop" || event === "SubagentStop"
        ? { decision: "block", reason: `outsider controller 不可用：${err?.message ?? err}` }
        : event === "PreToolUse"
          ? { hookSpecificOutput: { hookEventName: "PreToolUse", permissionDecision: "deny",
            permissionDecisionReason: `outsider controller 不可用：${err?.message ?? err}` } }
          : {};
      const codexReceiptFailureExit = CODEX_ATTACHED_CONTROL
        && !["PreToolUse", "Stop"].includes(event) ? 1 : 0;
      finish(lifecycleExit2 ? "" : JSON.stringify(ATTACHED_MODE || CONTROLLER_SOCKET ? failed : {}),
        "监督器自身出错，本次动作没有被放行 —— " + (err?.message ?? err),
        lifecycleExit2 ? 2 : codexReceiptFailureExit);
    }
  }
}
